type KeyPress = G2Observations['keyPresses'][number]

// 约定（2026-11-01 首席裁定，与 spec 注释同一口径）：
// obs.keyPresses 记录的是按键当时（移动前）的小船 x，不是移动后的 x。
// 评价必须按移动前 x 理解：一次按键的记录值是它出发的位置，不是落点；
// 记为 20 的那次右键按键（步数 10 时）落点是 30。判定不得把记录值当成落点。
// 最终位置以 live 船位 boatX（Scratch VM 对象状态）为准；boatX 缺失时，
// 依赖最终位置的判定保守地判为未完成。key-log 的记录语义不动。
const START = U3_BOAT_START_X

/** Step of press i as far as the pre-move log can prove it. A step whose
 *  landing is hidden by a green-flag reset (next pre is START while the boat
 *  was away from START) or by a missing live boat position is unknown. */
const stepAt = (presses: KeyPress[], index: number, finalX: number | undefined): number | null => {
  const pre = presses[index]?.x
  if (pre === undefined) return null
  if (index < presses.length - 1) {
    const next = presses[index + 1].x
    if (next === START && pre !== START) return null
    return next - pre
  }
  return finalX === undefined ? null : finalX - pre
}

export function evaluateG2U3Lesson(id: string, obs: G2Observations, boatX?: number): G2TaskState | null {
  if (id !== g2u3L01.id) return null
  const presses = obs.keyPresses
  const finalX = boatX !== undefined && Number.isFinite(boatX) ? Math.round(boatX) : undefined
  const last = presses[presses.length - 1]
  // 练习 A：从起点连续 3 次右键，记录值 0、10、20（落点 10、20、30）。
  const practiceA = presses.some((p, i) =>
    p.key === 'right arrow' && p.x === 0 &&
    presses[i + 1]?.key === 'right arrow' && presses[i + 1]?.x === 10 &&
    presses[i + 2]?.key === 'right arrow' && presses[i + 2]?.x === 20)
  // 练习 B：最后一次是左键、且小船最终回到原点、且此前按过右键。
  const practiceB = last?.key === 'left arrow' && last.x > START && finalX === START &&
    presses.slice(0, -1).some(p => p.key === 'right arrow')
  // 找错：此前按过左键（经历过左键状态），且最后一次左键确实向左移动。
  const debug = last?.key === 'left arrow' && finalX !== undefined && finalX < last.x &&
    presses.slice(0, -1).some(p => p.key === 'left arrow')
  // 创造：回到原点，且有一次按键步数既不是默认 ±10 也不是 0。
  const create = practiceB && presses.some((_, i) => {
    const step = stepAt(presses, i, finalX)
    return step !== null && step !== 0 && Math.abs(step) !== 10
  })
  return {practiceA, practiceB, debug, create}
}

export function observedPredictionG2U3(id: string, obs: G2Observations, boatX?: number): string | null {
  if (id !== g2u3L01.id) return null
  const first = obs.keyPresses[0]
  if (!first) return null
  if (first.key !== 'right arrow') return null
  const finalX = boatX !== undefined && Number.isFinite(boatX) ? Math.round(boatX) : undefined
  // 首按是右键：右键步数恒为正（1～20），故首按必然向右；只有在后续
  // 记录或最终位置皆未显示向右移动时，才判不动——不能只看首按的记录值，
  // 首按记录值恒为起点 0，看它永远是“不动”。
  const movedRight = obs.keyPresses.slice(1).some(p => p.x > START) || (finalX !== undefined && finalX > START)
  if (movedRight) return '向右走'
  if (obs.keyPresses.length === 1 && finalX === undefined) return '向右走'
  return '不动'
}
